import{_ as n,o as a,c as s,a2 as t}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"infrastructure/inference — 推理引擎适配器总览","description":"两种 InferenceEngine 实现的架构与选择指南","frontmatter":{"title":"infrastructure/inference — 推理引擎适配器总览","description":"两种 InferenceEngine 实现的架构与选择指南"},"headers":[],"relativePath":"architecture/infrastructure/inference/overview.md","filePath":"architecture/infrastructure/inference/overview.md","lastUpdated":1773869336000}'),i={name:"architecture/infrastructure/inference/overview.md"};function r(l,e,c,p,o,d){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="infrastructure-inference-—-推理引擎适配器总览" tabindex="-1">infrastructure/inference — 推理引擎适配器总览 <a class="header-anchor" href="#infrastructure-inference-—-推理引擎适配器总览" aria-label="Permalink to &quot;infrastructure/inference — 推理引擎适配器总览&quot;">​</a></h1><p><strong>源文件</strong>：<code>src/streammuse/infrastructure/inference/</code></p><p>所有推理引擎适配器均实现 <code>InferenceEngine</code> 协议（见 <a href="./../../domain/interfaces.html">domain/interfaces</a>）。</p><p>推理日志支持两种粒度：</p><ul><li><code>summary</code>（默认）：仅记录请求/响应摘要字段</li><li><code>full</code>：记录完整 request/response 事件内容（<code>inferences.json</code> 体积会显著增大）</li></ul><hr><h2 id="三种实现对比" tabindex="-1">三种实现对比 <a class="header-anchor" href="#三种实现对比" aria-label="Permalink to &quot;三种实现对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类</th><th>模式</th><th>说明</th></tr></thead><tbody><tr><td><code>HttpInferenceClient</code></td><td>远端 HTTP 服务器</td><td>将推理请求通过 REST API 发送到独立服务器进程</td></tr><tr><td><code>StanleyInferenceEngine</code></td><td>本地进程内</td><td>直接在当前进程中运行 RoFormer 模型</td></tr><tr><td><code>server_lekai + LekaiHttpBackend</code></td><td>远端 HTTP 服务器</td><td>FastAPI server 内使用 Lekai backend，并复用相同 HTTP 协议</td></tr></tbody></table><hr><h2 id="部署架构" tabindex="-1">部署架构 <a class="header-anchor" href="#部署架构" aria-label="Permalink to &quot;部署架构&quot;">​</a></h2><p><strong>HTTP 模式</strong>（默认、生产环境）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CLI 进程</span></span>
<span class="line"><span>  └── HttpInferenceClient</span></span>
<span class="line"><span>          │ HTTP POST /generate_accompaniment</span></span>
<span class="line"><span>          ▼</span></span>
<span class="line"><span>        推理服务器（FastAPI）</span></span>
<span class="line"><span>                ├── Stanley backend</span></span>
<span class="line"><span>                └── Lekai backend</span></span></code></pre></div><p><strong>Stanley 本地模式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CLI 进程</span></span>
<span class="line"><span>  └── StanleyInferenceEngine</span></span>
<span class="line"><span>          └── LegacyInferenceEngineStanley</span></span>
<span class="line"><span>                  └── RoFormerSymbolicTransformer</span></span></code></pre></div><hr><h2 id="两层适配器模式-stanley" tabindex="-1">两层适配器模式（Stanley） <a class="header-anchor" href="#两层适配器模式-stanley" aria-label="Permalink to &quot;两层适配器模式（Stanley）&quot;">​</a></h2><p>Stanley 引擎采用两层适配器隔离 Domain/Clean Architecture 模型与旧有 ML 代码：</p><ol><li><p><strong><code>StanleyInferenceEngine</code></strong>（接口适配层）：</p><ul><li>实现 <code>InferenceEngine</code> Protocol</li><li>负责 <code>MusicalEvent</code> ↔ <code>{pitch, tick, duration}</code> 字典的转换</li><li>遵循 close-at-horizon 策略</li></ul></li><li><p><strong><code>LegacyInferenceEngineStanley</code></strong>（ML 引擎层）：</p><ul><li>操作 <code>{pitch, tick, duration}</code> 字典和 piano-roll 张量</li><li>无 Domain 依赖，保持 ML 代码的独立性</li></ul></li></ol><hr><h2 id="文件结构" tabindex="-1">文件结构 <a class="header-anchor" href="#文件结构" aria-label="Permalink to &quot;文件结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inference/</span></span>
<span class="line"><span>├── http_client.py         # HttpInferenceClient</span></span>
<span class="line"><span>├── server_lekai.py        # Lekai HTTP server (FastAPI)</span></span>
<span class="line"><span>├── lekai_http_backend.py  # Lekai backend used by server_lekai</span></span>
<span class="line"><span>├── serialization.py       # event_to_dict / event_from_dict / timing_info_from_dict</span></span>
<span class="line"><span>├── stanley_engine.py      # StanleyInferenceEngine（接口适配层）</span></span>
<span class="line"><span>├── stanley_legacy.py      # LegacyInferenceEngineStanley（ML 引擎层）</span></span>
<span class="line"><span>├── stanley_stack/         # RoFormer 模型定义与预处理</span></span>
<span class="line"><span>│   ├── m2a_transformer.py</span></span>
<span class="line"><span>│   └── preprocess/</span></span>
<span class="line"><span>├── config/                # ML 配置 Schema（OmegaConf/Hydra 格式）</span></span>
<span class="line"><span>└── tokenization/          # MIDI tokenizer</span></span></code></pre></div><hr><h2 id="详细文档" tabindex="-1">详细文档 <a class="header-anchor" href="#详细文档" aria-label="Permalink to &quot;详细文档&quot;">​</a></h2><ul><li><a href="./http_client.html">http_client.md</a> — <code>HttpInferenceClient</code></li><li><a href="./overview.html">overview.md</a> — <code>server_lekai</code> / <code>LekaiHttpBackend</code> HTTP-first 架构说明</li><li><a href="./serialization.html">serialization.md</a> — 序列化/反序列化辅助函数</li><li><a href="./stanley_engine.html">stanley_engine.md</a> — <code>StanleyInferenceEngine</code>（接口适配层）</li><li><a href="./stanley_legacy.html">stanley_legacy.md</a> — <code>LegacyInferenceEngineStanley</code>（ML 引擎层）</li></ul>`,24)])])}const f=n(i,[["render",r]]);export{u as __pageData,f as default};
